<template>
  <div class="text-selection-test">
    <!-- Начальный экран -->
    <div v-if="!testStarted" class="intro-screen">
      <div class="intro-content">
        <div class="intro-icon">
          <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>
            <polyline points="14 2 14 8 20 8"></polyline>
            <line x1="16" y1="13" x2="8" y2="13"></line>
            <line x1="16" y1="17" x2="8" y2="17"></line>
            <polyline points="10 9 9 9 8 9"></polyline>
          </svg>
        </div>
        <h2>Тест: выделение слов</h2>
        <p>Проверьте свою внимательность и способность находить осмысленные слова в наборе букв. Выделяйте слова, щелкая и перетаскивая мышью.</p>
        <p class="instruction-note">Всего в тексте нужно найти <strong>{{ totalWords }}</strong> осмысленных слов.</p>
        <button @click="startTest" class="action-button">Начать тест</button>
      </div>
    </div>

    <!-- Экран с тестом -->
    <div v-else-if="!showResults" class="question-screen">
      <div class="progress-bar">
        <div class="progress-indicator" :style="{ width: `${(selectedWords.length / totalWords) * 100}%` }"></div>
      </div>
      
      <div class="question-counter">
        Найдено: {{ selectedWords.length }} из {{ totalWords }}
      </div>

      <div class="question-container">
        <h3 class="question-text">Выделите слова в тексте ниже:</h3>
        
        <div
          class="text-area"
          contenteditable="true"
          ref="editableText"
          @mouseup="handleSelection"
        >
          {{ text }}
        </div>
        
        <div class="found-words">
          <h4>Найденные слова:</h4>
          <div class="word-chips">
            <span 
              v-for="(word, index) in selectedWords" 
              :key="index"
              class="word-chip"
            >
              {{ word }}
            </span>
          </div>
        </div>
        
        <button @click="finishTest" class="action-button">Завершить тест</button>
      </div>
    </div>

    <!-- Экран с результатами -->
    <div v-if="showResults" class="results-screen">
      <div class="results-content">
        <div class="results-icon" :class="{ 'high-score': selectedWords.length >= totalWords * 0.7 }">
          <svg v-if="selectedWords.length >= totalWords * 0.7" xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
            <polyline points="22 4 12 14.01 9 11.01"></polyline>
          </svg>
          <svg v-else xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="10"></circle>
            <path d="M8 15h8M10 9h.01M14 9h.01"></path>
          </svg>
        </div>
        
        <h2 class="results-title">Результаты теста</h2>
        
        <div class="score-display">
          <div class="score-circle">
            <span class="score-value">{{ selectedWords.length }}</span>
            <span class="score-total">/{{ totalWords }}</span>
          </div>
          <p class="score-label">найденных слов</p>
        </div>
        
        <div class="result-message">
          <p v-if="selectedWords.length === totalWords">Отличный результат! Вы нашли все слова.</p>
          <p v-else-if="selectedWords.length >= totalWords * 0.7">Хороший результат! Вы нашли большинство слов.</p>
          <p v-else-if="selectedWords.length >= totalWords * 0.5">Неплохой результат. Есть потенциал для улучшения.</p>
          <p v-else>Внимательность можно тренировать! Попробуйте еще раз.</p>
        </div>
        
        <div v-if="selectedWords.length < totalWords" class="missed-words">
          <h4>Пропущенные слова:</h4>
          <div class="word-chips">
            <span 
              v-for="word in missedWords" 
              :key="word"
              class="word-chip missed"
            >
              {{ word }}
            </span>
          </div>
        </div>
        
        <button @click="restartTest" class="action-button">Пройти тест снова</button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      text: `клодфитренмстоловоапряглицетыпошлидровоставракосылимонедпрыгаютвребелокречьщедорогакапустаквартирымыркодчебылкитюленувлесузебраскидаюхолстореворыпалкаочагпрокартайлебедяжукстарыйовражекореньдроваимеломшапканоркастихлосолнцезвенитшансгрибоклепестокпартастеклопосудажучокдверьлупень`,
      words: ["белок", "стол", "прыгают", "капуста", "лимон", "квартиры", "дорога", "код", "кит", "лес", "зебра",
              "палка", "очаг", "жук", "овраг", "дрова", "шапка", "норка", "солнце", "гриб", "парта", "жучок", "дверь"],
      selectedWords: [],
      totalWords: 23,
      showResults: false,
      testStarted: false
    };
  },
  computed: {
    missedWords() {
      return this.words.filter(word => !this.selectedWords.includes(word));
    }
  },
  methods: {
    startTest() {
      this.testStarted = true;
      this.selectedWords = [];
      this.showResults = false;
      this.$emit('test-start');
    },
    
    handleSelection() {
      const selection = window.getSelection().toString().trim();
      if (selection && !this.selectedWords.includes(selection) && this.words.includes(selection)) {
        this.selectedWords.push(selection);
      }

      if (selection.charAt(0) === "[" && selection.charAt(selection.length-1) === "]" ){
        this.text = this.text.replace(selection, selection.slice(1, selection.length-1))
      }
      else {
        let firstInsertion = this.text.slice(0, window.getSelection().anchorOffset) + '[' + this.text.slice(window.getSelection().anchorOffset);
        let adjustedIndex2 = window.getSelection().focusOffset + 1;
        this.text = firstInsertion.slice(0, adjustedIndex2) + ']' + firstInsertion.slice(adjustedIndex2);
      }
    },
    
    finishTest() {
      this.showResults = true;
      this.$emit('test-complete', this.selectedWords.length, this.totalWords);
    },
    
    restartTest() {
      this.text = `клодфитренмстоловоапряглицетыпошлидровоставракосылимонедпрыгаютвребелокречьщедорогакапустаквартирымыркодчебылкитюленувлесузебраскидаюхолстореворыпалкаочагпрокартайлебедяжукстарыйовражекореньдроваимеломшапканоркастихлосолнцезвенитшансгрибоклепестокпартастеклопосудажучокдверьлупень`;
      this.selectedWords = [];
      this.showResults = false;
      this.$emit('test-start');
    }
  }
};
</script>

<style>
.text-selection-test {
  max-width: 800px;
  margin: 0 auto;
  padding: 0;
  font-family: 'Roboto', sans-serif;
  position: relative;
  overflow: hidden;
  height: 100%;
}

/* Стили начального экрана */
.intro-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 2rem;
  border-radius: 12px;
  background-color: white;
}

.intro-content {
  max-width: 500px;
}

.intro-icon {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  background-color: #f0f4ff;
  border-radius: 50%;
  margin-bottom: 1rem;
  color: #3b4ce2;
}

.intro-screen h2 {
  color: #3b4ce2;
  font-size: 28px;
  margin-bottom: 1rem;
}

.intro-screen p {
  color: #4b5563;
  margin-bottom: 1rem;
  font-size: 16px;
  line-height: 1.5;
}

.instruction-note {
  font-weight: 500;
  color: #1f2937;
  margin-bottom: 2rem;
}

/* Стили экрана с тестом */
.question-screen {
  position: relative;
  padding: 0;
  background-color: white;
  border-radius: 12px;
  overflow: hidden;
}

.progress-bar {
  height: 6px;
  background-color: #e5e7eb;
  width: 100%;
}

.progress-indicator {
  height: 100%;
  background-color: #3b4ce2;
  transition: width 0.3s ease;
}

.question-counter {
  padding: 1rem;
  text-align: center;
  font-size: 14px;
  color: #6b7280;
  border-bottom: 1px solid #f3f4f6;
}

.question-container {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.question-text {
  font-size: 18px;
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 1.5rem;
  text-align: center;
}

.text-area {
  margin: 0 auto 1.5rem;
  padding: 20px;
  border: 2px solid #e2e8f0;
  border-radius: 8px;
  width: 100%;
  max-width: 600px;
  min-height: 200px;
  overflow-y: auto;
  white-space: pre-wrap;
  font-family: 'Courier New', monospace;
  background: #f8fafc;
  user-select: text;
  color: #1e293b;
  font-size: 24px;
  line-height: 1.6;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
  text-align: justify;
  letter-spacing: 1px;
}

.found-words {
  width: 100%;
  max-width: 600px;
  margin-bottom: 1.5rem;
}

.found-words h4 {
  font-size: 16px;
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 0.75rem;
}

.word-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.word-chip {
  padding: 0.5rem 0.75rem;
  background-color: #e0f2fe;
  color: #0369a1;
  border-radius: 1rem;
  font-size: 0.875rem;
  font-weight: 500;
}

.word-chip.missed {
  background-color: #fef9c3;
  color: #a16207;
}

/* Стили экрана результатов */
.results-screen {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background-color: white;
  border-radius: 12px;
}

.results-content {
  max-width: 600px;
}

.results-icon {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  background-color: #fee2e2;
  border-radius: 50%;
  margin-bottom: 1.5rem;
  color: #ef4444;
}

.results-icon.high-score {
  background-color: #dcfce7;
  color: #10b981;
}

.results-title {
  color: #1f2937;
  font-size: 24px;
  margin-bottom: 1.5rem;
}

.score-display {
  margin-bottom: 1.5rem;
}

.score-circle {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  width: 120px;
  height: 120px;
  background-color: #f0f4ff;
  border-radius: 50%;
  margin-bottom: 0.5rem;
  position: relative;
}

.score-value {
  font-size: 40px;
  font-weight: 700;
  color: #3b4ce2;
}

.score-total {
  font-size: 20px;
  color: #6b7280;
  position: absolute;
  top: 50%;
  right: 30px;
}

.score-label {
  color: #6b7280;
  font-size: 14px;
  margin: 0;
}

.result-message {
  margin-bottom: 1.5rem;
  padding: 1rem;
  background-color: #f9fafb;
  border-radius: 8px;
}

.result-message p {
  margin: 0;
  color: #4b5563;
  font-size: 16px;
  line-height: 1.5;
}

.missed-words {
  margin-bottom: 2rem;
  width: 100%;
}

.missed-words h4 {
  font-size: 16px;
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 0.75rem;
}

.action-button {
  padding: 0.75rem 1.5rem;
  background-color: #3b4ce2;
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.action-button:hover {
  background-color: #2d3ebd;
}

.action-button:active {
  transform: translateY(1px);
}

/* Адаптивность для мобильных устройств */
@media (max-width: 640px) {
  .intro-screen h2, .results-title {
    font-size: 22px;
  }
  
  .intro-screen p, .question-text, .result-message p {
    font-size: 14px;
  }
  
  .score-circle {
    width: 100px;
    height: 100px;
  }
  
  .score-value {
    font-size: 32px;
  }
  
  .score-total {
    font-size: 18px;
    right: 25px;
  }
  
  .intro-icon, .results-icon {
    width: 60px;
    height: 60px;
  }
  
  .text-area {
    font-size: 18px;
    padding: 15px;
    min-height: 150px;
  }
  
  .word-chip {
    font-size: 0.75rem;
    padding: 0.375rem 0.625rem;
  }
}
</style>